func TestCountEven(t *testing.T) {
	tests := []struct {
		name string
		nums []int
		want int
	}{
		{"empty", nil, 0},
		{"all even", []int{2, 4, 6}, 3},
		{"all odd", []int{1, 3, 5}, 0},
		{"mixed", []int{1, 2, 3, 4, 5}, 2},
		{"with zero and negatives", []int{0, -2, -3, 7}, 2},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := countEven(tt.nums); got != tt.want {
				t.Fatalf("countEven(%v) = %d, want %d", tt.nums, got, tt.want)
			}
		})
	}
}

